// One continuous 18.6-second CSS animation per scene. No phase timers or DOM replacement.
export const duration = 18600;
export const captions = {
  voice: ['ボイスチャンネルに参加済みのメンバーが /voice_web join を実行。Botが同じチャンネルへ参加します。', 'メンバーはマイクを使わずテキストを投稿。音声合成後、ボイスチャンネルのBotが発話し、アイコンに緑のリングが灯ります。', 'あらかじめ読む言語を登録したAliceへのメンションを翻訳し、元の投稿へ返信します。翻訳結果は読み上げません。'],
  weather: ['管理者が /set_eq_channel で地震・津波情報の通知先を設定します。返答は本人だけに表示されます。', '地震情報を受信し、設定済みの震度条件と重複通知を確認します。このデモは震度3以上の設定例です。', '震源・規模・深さ・最大震度をDiscordへ通知します。表示している地震・数値はすべて架空です。'],
  stream: ['左側のモジュール一覧からテキストを追加し、内容を入力。配信用の出力はまだ変更されません。', '選択枠をドラッグして配置を調整。時計と背景パネルを重ね、編集画面内でレイアウトを整えます。', '「保存して配信に反映」を実行。OBS用出力が更新され、編集用の選択枠やガイドは表示されません。'],
  moral: ['試験で最高点を取るという目標に対し、候補行動と代替案を用意します。実プロジェクトはPythonのCLI・ライブラリです。', '未来の出来事を予測し、当事者ごとに被害・権利・同意・公平性・可逆性・不確実性を評価します。', '無断アクセスはBLOCK。許可された自力解答へ変更し、最終判断はMODIFY。Dry Runの記録を返します。'],
  proxy: ['ブラウザからのサンプル通信がプロキシを通り、アクセスログに追加されます。', 'POSTリクエストの本文からメールアドレス形式を検出。ログの詳細で送信内容と検出結果を確認できます。', 'ブロック対象ドメインへのアクセスを拒否し、ログに記録。普段見えない通信とポリシーの働きを理解できます。'],
  soccer: ['6対6の配置から、パスレーン・相手との距離・シュートコースをもとに候補位置を評価します。色の分布は説明用です。', '受け手が高評価の空間へ移動。相手の守備位置も変わる中で、パスをつなぎます。', '受け手がボールを運び、空いたコースへシュート。実装では行動の成功・失敗を重みの更新に利用します。']
};
const badge = '<em class="app-badge">APP</em>';
const avatar = (letter, cls = '') => `<i class="dc-avatar ${cls}">${letter}</i>`;
const msg = (name, content, cls = '', initial = 'A') => `<div class="dc-message ${cls}">${avatar(initial, name === 'Member' ? '' : 'bot-avatar')}<div><b>${name} ${name !== 'Member' ? badge : ''}</b>${content}</div></div>`;
const pane = (n, html) => `<div class="scene-phase phase-${n}">${html}</div>`;
const shell = (kind, body) => `<div class="scene-viewport continuous" data-kind="${kind}"><div class="scene-scaler"><div class="scene-camera">${body}</div></div><div class="sequence-progress" aria-hidden="true"><i></i></div></div>`;
function voice() {
  const sidebar = `<aside class="dc-sidebar"><strong>amz community⌄</strong><small>テキストチャンネル</small><div class="dc-channel selected"># voice-chat</div><small>ボイスチャンネル</small><div class="dc-channel">◖ General</div><div class="vc-person">${avatar('A')}<span>Member</span><small>マイクOFF</small></div><div class="vc-person">${avatar('L','alice-avatar')}<span>Alice</span></div><div class="vc-person vc-bot">${avatar('y.','bot-avatar speaker-avatar')}<span>Yomiage ${badge}</span></div><div class="voice-link">◖ ボイス接続中<small>General / amz community</small></div></aside>`;
  const phases = pane(0, msg('Member','<code>/voice_web join</code>') + msg('Yomiage','<div class="dc-embed"><b>🎤 ボイスチャンネルに参加しました！</b><p>接続先: General<br>読み上げチャンネル: voice-chat</p></div>','delayed-response','y.')) + pane(1, msg('Member','<p class="typed-message">こんばんは！今日は聞き専で参加します。</p>') + '<div class="voice-explainer"><small>動作の解説</small><br><span class="quiet-mic">⌁ マイクはOFFのまま</span><p>テキストが、ボイスチャンネルの声になる。</p><span class="sound-bars">'+ '<i></i>'.repeat(18) +'</span></div>') + pane(2,msg('Member','<p><span class="dc-mention">@Alice</span> 明日は何時に集まりますか？</p>') + msg('Yomiage','<small class="reply-trace">↳ Member のメッセージに返信</small><div class="dc-embed translated"><small>English (US)</small><p>What time shall we meet tomorrow?</p></div>','delayed-response','y.'));
  return shell('voice',`<div class="discord-scene">${sidebar}<section class="dc-main"><header># voice-chat <small>コミュニティ</small></header><div class="dc-messages">${phases}</div><div class="dc-compose">＋ <span class="compose-copy">メッセージを送信 #voice-chat</span></div></section></div>`);
}
function weather() {
  return shell('weather',`<div class="discord-scene"><aside class="dc-sidebar"><strong>amz community⌄</strong><small>テキストチャンネル</small><div class="dc-channel"># general</div><div class="dc-channel selected"># 地震速報 <span class="notification-dot"></span></div><small>アプリ</small><div class="vc-person">${avatar('s.','weather-avatar')}<span>Shindo ${badge}</span></div><div class="sample-tag">DEMO / 架空の地震情報</div></aside><section class="dc-main"><header># 地震速報 <small>地震・津波情報</small></header><div class="dc-messages">${pane(0,msg('Member','<code>/set_eq_channel</code><p>channel: #地震速報</p>')+msg('Shindo','<div class="dc-embed"><b>地震・津波情報の通知先を<br><span class="dc-mention">#地震速報</span> に設定しました。</b><p>このメッセージはあなただけに表示されています</p></div>','delayed-response','s.'))}${pane(1,'<div class="chat-idle"><span># 地震速報</span><p>新しい地震情報を待っています</p></div>')}${pane(2,msg('Shindo','<div class="dc-embed quake-notice"><small>DEMO / 架空の地震情報</small><b>地震情報</b><div class="quake-fields"><span>震源<strong>デモ沖</strong></span><span>規模<strong>M 5.2</strong></span><span>深さ<strong>10 km</strong></span><span>最大震度<strong class="quake-intensity">4</strong></span><span>発生時刻<strong>20:30（架空）</strong></span><span>津波<strong>心配なし</strong></span></div><small>表示形式: P2P地震情報 / 気象庁</small></div>','delayed-response','s.'))}</div><div class="dc-compose">＋ メッセージを送信 #地震速報</div></section></div><aside class="process-overlay weather-process"><small>バックグラウンド処理の解説</small><b>地震情報を受信 → 震度を照合 → 重複確認</b><div class="process-track"><i></i></div><span>架空の最大震度 4 / 設定済みの通知条件: 震度3以上</span></aside>`);
}
function stream() {
  return shell('stream',`<div class="editor-scene"><header><b>◫ Streaming Studio</b><span>1920 × 1080</span><div class="save-control">保存して配信に反映</div></header><div class="editor-workspace"><aside class="editor-modules"><small>モジュールを追加</small><div class="add-text">＋ テキスト</div><div>＋ 時計</div><div>＋ パネル</div><small>レイヤー</small><p>Ｔ タイトル</p><p class="after-layout clock-added">◷ 時計</p><p class="after-layout panel-added">▧ 背景パネル</p></aside><section class="editor-canvas"><div class="editable-title"><span>JUST CHATTING.</span><i class="resize-handle"></i></div><div class="editor-clock after-layout clock-added">20:30<small>ASIA / TOKYO</small></div><div class="editor-panel after-layout panel-added">今日も、ゆっくり話そう。<small>WELCOME TO MY STREAM</small></div></section><aside class="editor-inspector"><small>選択したモジュール</small><b>テキスト</b><span>内容</span><div>JUST CHATTING.</div><span>位置 / サイズ</span><div>ドラッグで位置を調整</div><span>文字サイズ</span><div>64 px</div></aside></div><footer><span class="edit-status">編集中 · 未保存</span><span class="saved-status">✓ 保存済み · OBS出力へ反映</span><small>取り消し ↶　やり直し ↷</small></footer><span class="demo-cursor" aria-hidden="true"><i class="cursor-click"></i><svg viewBox="0 0 24 30"><path d="M1 1L1 24L7 19L12 29L17 26L12 17L22 17Z" fill="white" stroke="#34263d" stroke-width="1.5" stroke-linejoin="round"/></svg></span></div><aside class="obs-preview"><header><b>OBS / ブラウザソース</b><small>/overlay</small></header><div><strong>JUST CHATTING.</strong><span>20:30</span><p>今日も、ゆっくり話そう。</p></div><small>選択枠・編集ガイドは配信に出ません</small></aside>`);
}
function moral() {
  return shell('moral',`<div class="research-scene"><header><b>Artificial Moral Architecture</b><small>PIPELINE VISUALIZATION / v0.1</small></header><div class="research-goal"><small>GOAL</small><b>試験で最高点を取る</b></div><div class="research-path"><div class="pipeline-node candidate-node"><small>01 / PLAN</small><b>候補行動</b><p>無断アクセス<br><span>代替案: 自力で解答</span></p></div><span>→</span><div class="pipeline-node evaluation-node"><small>02 / EVALUATE</small><b>未来と当事者への影響</b><div class="moral-axes">${['Harm','Rights','Consent','Fairness','Reversibility','Uncertainty'].map(x=>`<span>${x}</span>`).join('')}</div></div><span>→</span><div class="pipeline-node decision-node"><small>03 / COMMIT</small><b class="moral-result">MODIFY</b><p><span class="block-tag">BLOCK</span> 無断アクセス<br><span class="allow-tag">ALLOW</span> 自力解答</p></div></div><div class="research-terminal"><small>Python / Dry Run</small><code class="terminal-line terminal-a">$ python examples/demo.py --json</code><code class="terminal-line terminal-b">&gt; foresight → stakeholders → moral_evaluation</code><code class="terminal-line terminal-c">&gt; decision: MODIFY · selected: SOLVE · status: simulated</code></div><p class="research-note">実行結果を説明する図解です。外部モデルへの接続は今後の研究対象です。</p></div>`);
}
function proxy() {
  return shell('proxy',`<div class="inspection-scene"><header><b>Web Browsing Inspection</b><small>Dashboard / サンプル通信</small></header><div class="request-flow"><span>ブラウザ</span><i>→</i><span class="proxy-node">Proxy :8080</span><i>→</i><span>Webサイト</span><b class="request-packet"></b></div><div class="inspection-table"><div class="inspection-row table-labels"><span>METHOD</span><span>URL</span><span>STATUS / PII</span></div><div class="inspection-row log-one"><span>GET</span><span>https://example.com/</span><em>200 OK</em></div><div class="inspection-row log-two"><span>POST</span><span>https://example.test/form</span><em class="pii-tag">EMAIL</em></div><div class="inspection-row log-three"><span>GET</span><span>https://blocked.test/</span><em class="block-tag">BLOCKED</em></div></div><div class="request-detail"><small>POST / リクエスト本文・検出結果</small><code>{ "email": "<mark>demo@example.test</mark>" }</code><p>検出: メールアドレス形式</p></div><div class="blocked-page"><b>アクセスをブロックしました</b><p>blocked.test はブロック対象に登録されています。</p><small>アクセスログに blocked: true を記録</small></div></div>`);
}
function soccer() {
  const cells = Array.from({length:112},(_,i)=>{const x=35+(i%16)*33,y=18+Math.floor(i/16)*33;const score=Math.max(0,1-Math.hypot((x-405)/280,(y-72)/150));return `<rect x="${x}" y="${y}" width="31" height="31" fill="hsl(${55+score*45} 80% 60%)" opacity="${(score*.42).toFixed(2)}"/>`;}).join('');
  const blues=[[42,135],[125,65],[135,133],[120,205],[264,78],[245,200]];
  const reds=[[558,135],[495,65],[493,133],[485,205],[368,104],[370,205]];
  const robot=(xy,i,team)=>`<g class="robot ${team} robot-${i}" style="--rx:${xy[0]}px;--ry:${xy[1]}px"><circle r="12"/><path d="M 3 -7 L 8 0 L 3 7"/><text y="4" text-anchor="middle">${i}</text></g>`;
  return shell('soccer',`<div class="football-scene"><header><b>SSL Robot AI</b><small>6 vs 6 / POSITION SCORING</small></header><div class="football-legend"><span>● BLUE</span><span>● RED</span><span class="heat-key">候補位置の評価　低 ▰▰▰ 高</span></div><svg class="tactics-field" viewBox="0 0 600 270" role="presentation"><rect x="18" y="9" width="564" height="252" fill="#234c39"/><g class="score-cells">${cells}</g><g class="field-lines" fill="none" stroke="#c8e1cb" stroke-width="1.2"><rect x="18" y="9" width="564" height="252"/><path d="M300 9V261 M18 85H77V185H18 M582 85H523V185H582"/><circle cx="300" cy="135" r="37"/><path d="M18 112H7V158H18 M582 112H593V158H582"/></g><path class="pass-path" d="M264 78L418 62L563 129" fill="none" stroke="#d1f994" stroke-width="2" stroke-dasharray="5 6"/><circle class="target-position" cx="418" cy="62" r="18" fill="none" stroke="#d1f994" stroke-dasharray="4 3"/>${blues.map((xy,i)=>robot(xy,i,'blue-team')).join('')}${reds.map((xy,i)=>robot(xy,i,'red-team')).join('')}<circle class="match-ball" r="5" fill="#ffbe75" stroke="#f7dcac"/></svg><footer><b class="soccer-phase-label"><span class="label-0">SCAN / 候補地点を評価</span><span class="label-1">PASS / 空いた味方へ</span><span class="label-2">SHOOT / ゴールへの経路</span></b><small>Ri-one導入システムのプロトタイプ</small></footer></div>`);
}
const scenes = {voice,weather,stream,moral,proxy,soccer};
export function renderDemoScene(project) {
  if (!scenes[project.kind]) throw new Error('Unknown demo kind: '+project.kind);
  return scenes[project.kind]();
}
